  es: { label: "Spanish", html: "es-AR", og: "es_AR" },
  en: { label: "English", html: "en-US", og: "en_US" },
  it: { label: "Italian", html: "it-IT", og: "it_IT" },
  fr: { label: "French", html: "fr-FR", og: "fr_FR" },
